function validate([digits, n]) {
  if (!Array.isArray(digits) || digits.length < 1 || digits.length > 9) return 'digits needs 1 to 9 entries.';
  for (let i = 0; i < digits.length; i++) {
    if (typeof digits[i] !== 'string' || !/^[1-9]$/.test(digits[i])) return "Each entry of digits is one character from '1' to '9'.";
    if (i > 0 && digits[i - 1] >= digits[i]) return 'digits must be distinct and in ascending order.';
  }
  if (!Number.isInteger(n) || n < 1 || n > 1000000000) return 'n is an integer from 1 to 10^9.';
  return null;
}

