function atMostNGivenDigitSet(digits, n) {
  const text = String(n);
  const length = text.length;
  const base = digits.length;
  const dp = new Array(length + 1).fill(0);
  dp[length] = 1;

  for (let i = length - 1; i >= 0; i--) {
    const current = text[i];
    for (const digit of digits) {
      if (digit < current) {
        dp[i] += base ** (length - i - 1);
      } else if (digit === current) {
        dp[i] += dp[i + 1];
      }
    }
  }

  let shorter = 0;
  for (let size = 1; size < length; size++) {
    shorter += base ** size;
  }
  return dp[0] + shorter;
}

