function atMostNGivenDigitSet(digits, n) {
  const values = digits.map(Number);
  let count = 0;
  const extend = (value) => {
    for (const d of values) {
      const next = value * 10 + d;
      if (next > n) continue;
      count++;
      extend(next);
    }
  };
  extend(0);
  return count;
}

