  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pool[i], pool[j]] = [pool[j], pool[i]];
  }
  const take = rand() < 0.15 ? 9 : 1 + Math.floor(rand() * 9);
  const digits = pool.slice(0, take).sort();
  if (size === 'large' && rand() < 0.2) return [digits, 1000000000];
  const len = size === 'large' ? 9 : 1 + Math.floor(rand() * 5);
  const mode = rand();
  let text = '';
  for (let i = 0; i < len; i++) {
    if (mode < 0.45) text += digits[Math.floor(rand() * digits.length)];
    else text += String(i === 0 ? 1 + Math.floor(rand() * 9) : Math.floor(rand() * 10));
  }
  let n = Number(text);
  if (mode > 0.85) n += rand() < 0.5 ? 1 : -1;
  n = Math.min(Math.max(n, 1), 1000000000);
